#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sched.h>
#include <errno.h>

void *worker_thread(void *arg) {
    printf("Thread running...\n");
    // Simulate work
    return NULL;
}

int main() {
    pthread_t thread;
    int ret, policy_get;
    struct sched_param param_set, param_get;

    if (pthread_create(&thread, NULL, worker_thread, NULL) != 0) {
        perror("pthread_create failed");
        return 1;
    }

    // 1. Determine maximum real-time priority for SCHED_FIFO
    int max_prio = sched_get_priority_max(SCHED_FIFO);
    if (max_prio == -1) {
        perror("sched_get_priority_max");
        pthread_join(thread, NULL);
        return 1;
    }

    // Set desired parameters: SCHED_FIFO and highest priority
    param_set.sched_priority = max_prio;
    int target_policy = SCHED_FIFO;

    printf("Attempting to set SCHED_FIFO policy with priority %d.\n", param_set.sched_priority);

    // 2. Set the scheduling parameters
    ret = pthread_setschedparam(thread, target_policy, &param_set);

    if (ret != 0) {
        if (ret == EPERM) {
            fprintf(stderr, "Error: EPERM (%d). Cannot set real-time priority without proper permissions (try running as root/sudo).\n", EPERM);
        } else {
            fprintf(stderr, "Error setting parameters: %d\n", ret);
        }
    }

    // 3. Get the parameters to verify the current state
    ret = pthread_getschedparam(thread, &policy_get, &param_get);

    if (ret != 0) {
        fprintf(stderr, "Error getting parameters: %d\n", ret);
    } else {
        const char *policy_name = (policy_get == SCHED_FIFO) ? "SCHED_FIFO" :
                                  (policy_get == SCHED_RR) ? "SCHED_RR" : "SCHED_OTHER";
        printf("\n--- Current Thread Attributes ---\n");
        printf("Policy: %s\n", policy_name);
        printf("Priority: %d\n", param_get.sched_priority);
    }

    pthread_join(thread, NULL);
    return 0;
}
